const { AsyncLocalStorage } = require("node:async_hooks");
const { Server } = require("node:http");
const { writeFileSync } = require("node:fs");
const inspector = require("node:inspector");
const state = new AsyncLocalStorage();
const emit = Server.prototype.emit;
const profile = process.env.HOME_CHAT_PROFILE === "1";
const session = profile ? new inspector.Session() : null;
let profiled = 0;
if (session) {
  session.connect();
  session.post("Profiler.enable");
}
Server.prototype.emit = function(event, ...args) {
  if (event !== "request") return emit.call(this, event, ...args);
  const [req, res] = args;
  if (req.headers["x-moneo-benchmark"] === "stop" && req.url === "/api/health?benchmark=stop") {
    res.end("stopped");
    setImmediate(() => process.exit(0));
    return true;
  }
  const tracked = profile && req.headers["x-moneo-profile"] === "1";
  if (!tracked) return emit.call(this, event, ...args);
  const t = performance.now();
  const path = new URL(req.url, "http://localhost").pathname;
  const capture = profile && path === "/" && profiled++ === 0;
  if (capture) session.post("Profiler.start");
  res.on("finish", () => {
    console.log("[BENCH]", path, "finished", Math.round(performance.now()-t));
    if (capture) session.post("Profiler.stop", (error, value) => {
      if (!error) writeFileSync(process.env.BENCH_PROFILE_FILE, JSON.stringify(value.profile));
    });
  });
  return state.run(t, () => emit.call(this, event, ...args));
};
const realFetch = globalThis.fetch;
globalThis.fetch = async function(input, init) {
  const url = new URL(input instanceof Request ? input.url : String(input));
  const started = state.getStore();
  const t = performance.now();
  const log = (status) => {
    if (profile && started !== undefined) console.log("[BENCH]", Math.round(t-started), init?.method ?? "GET", url.pathname, Math.round(performance.now()-started), status);
  };
  if (url.hostname === "api.openai.com" && url.pathname === "/v1/responses") {
    const body = JSON.parse(init.body);
    const usage = {input_tokens: 5, output_tokens: 5, total_tokens: 10, input_tokens_details: {cached_tokens: 0}, output_tokens_details: {reasoning_tokens: 0}};
    const response = {id: "resp_qa", created_at: 1, model: body.model, usage};
    const item = {id: "msg_qa", type: "message", role: "assistant", content: [{type:"output_text", text: body.stream ? "The QA answer." : '{"title":"QA benchmark","vague":false}', annotations: []}]};
    log("fake");
    if (!body.stream) return Response.json({...response, output: [item]});
    const events = [
      {type:"response.created", response},
      {type:"response.output_item.added", output_index:0, item},
      {type:"response.output_text.delta", item_id:item.id, output_index:0, delta:"The QA answer."},
      {type:"response.output_item.done", output_index:0, item},
      {type:"response.completed", response},
    ];
    return new Response(events.map(event => "data: " + JSON.stringify(event) + "\n\n").join(""), {headers: {"content-type":"text/event-stream"}});
  }
  if (!["127.0.0.1", "localhost", "[::1]"].includes(url.hostname)) throw new Error("Blocked outbound QA request to " + url.hostname);
  const response = await realFetch(input, init);
  log(response.status);
  return response;
